package com.masterclass.inventory.service; import com.masterclass.inventory.dto.InventoryDtos.*; import com.masterclass.inventory.entity.*; import com.masterclass.inventory.exception.BusinessException; import com.masterclass.inventory.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class InventoryServiceTest { @Mock ProductRepository products; @Mock InventoryMovementRepository movements; @InjectMocks InventoryService service; @Test void rejectsAdjustmentOutBeyondStock(){ Product p=Product.builder().id(1L).sku("RCE-001").status(ProductStatus.ACTIVE).currentStock(5).build(); when(products.findById(1L)).thenReturn(Optional.of(p)); assertThatThrownBy(()->service.adjust(new AdjustmentCommand(1L,6,MovementType.ADJUSTMENT_OUT,"tester"))).isInstanceOf(BusinessException.class).hasMessageContaining("Insufficient stock"); assertThat(p.getCurrentStock()).isEqualTo(5); verify(movements,never()).save(any()); } @Test void rejectsInvalidAdjustmentType(){ assertThatThrownBy(()->service.adjust(new AdjustmentCommand(1L,1,MovementType.SALE,"tester"))).isInstanceOf(BusinessException.class).hasMessageContaining("Invalid adjustment type"); verify(products,never()).findById(any()); verify(movements,never()).save(any()); } @Test void replenishIncreasesStockAndRecordsMovement(){ Product p=Product.builder().id(1L).sku("APL-001").status(ProductStatus.ACTIVE).currentStock(5).build(); when(products.findById(1L)).thenReturn(Optional.of(p)); when(movements.save(any())).thenAnswer(i->i.getArgument(0)); MovementResponse r=service.replenish(new InventoryCommand(1L,3,"tester")); assertThat(p.getCurrentStock()).isEqualTo(8); assertThat(r.movementType()).isEqualTo(MovementType.REPLENISHMENT); assertThat(r.quantity()).isEqualTo(3); verify(movements).save(any(InventoryMovement.class)); } }
